Ast:
{
                $parts=$_ -split '\|',4

                if($parts.Count -ne 4)
                {
                    throw "INVALID ROW ENCODING: $_"
                }

                [pscustomobject][ordered]@{
                    'Course ID'            = $parts[0]
                    'University Course ID' = ConvertFrom-B64 $parts[1]
                    'Course Code'          = ConvertFrom-B64 $parts[2]
                    'Course Title'         = ConvertFrom-B64 $parts[3]
                }
            }
